// Runtime globals (Fetcher, DurableObjectNamespace, Cloudflare.Env) come from
// worker-configuration.d.ts, generated by `wrangler types`.
export interface Env extends Cloudflare.Env {
  DEMO_PROXY_SENTIMENT?: string; // "false" disables the F&G proxy fallback
  CRYPTOPANIC_API_KEY?: string;
  NEWSAPI_KEY?: string;
}
